int main(void) {
    clock_init();
    gpio_init();
    uart_init();
    timer_init();          // ISR sets a 'tick' flag at fixed rate
    for (;;) {
        if (tick) {        // volatile, set by timer ISR
            tick = 0;
            read_sensors();
            run_control();
            update_outputs();
        }
        service_comms();   // best-effort background work
        // optionally: __WFI();  // sleep until next interrupt
    }
}
